const iframe = document.querySelector('#storybook-preview-iframe');
const iframeRect = iframe.getBoundingClientRect();
const doc = iframe.contentDocument;
const btn = doc.querySelector('[aria-label*="Next" i]');
const btnRect = btn.getBoundingClientRect();
JSON.stringify({
  windowInnerWidth: window.innerWidth,
  windowInnerHeight: window.innerHeight,
  devicePixelRatio: window.devicePixelRatio,
  iframeRect: {x: iframeRect.x, y: iframeRect.y, width: iframeRect.width, height: iframeRect.height},
  btnRect: {x: btnRect.x, y: btnRect.y, width: btnRect.width, height: btnRect.height},
  btnAriaLabel: btn.getAttribute('aria-label'),
});

const iframe = document.querySelector('#storybook-preview-iframe');
const doc = iframe.contentDocument;
const scrollContainer = doc.querySelector('[data-card-slot="carousel"]')?.parentElement || doc.querySelectorAll('a')[0]?.closest('div')?.parentElement;
// More reliable: find the element with scrollSnapType by checking overflow-x auto
const candidates = [...doc.querySelectorAll('div')].filter(el => getComputedStyle(el).overflowX === 'auto');
const container = candidates[0];
JSON.stringify({
  activeElementTag: doc.activeElement.tagName,
  activeElementLabel: doc.activeElement.getAttribute('aria-label'),
  activeElementHref: doc.activeElement.getAttribute('href'),
  containerFound: !!container,
  scrollLeftBefore: container ? container.scrollLeft : null,
});

const iframe = document.querySelector('#storybook-preview-iframe');
const doc = iframe.contentDocument;
const candidates = [...doc.querySelectorAll('div')].filter(el => getComputedStyle(el).overflowX === 'auto');
const container = candidates[0];
JSON.stringify({
  activeElementTag: doc.activeElement.tagName,
  activeElementLabel: doc.activeElement.getAttribute('aria-label'),
  activeElementHref: doc.activeElement.getAttribute('href'),
  scrollLeftAfter: container ? container.scrollLeft : null,
  containerWidth: container ? container.clientWidth : null,
});

const iframe = document.querySelector('#storybook-preview-iframe');
const doc = iframe.contentDocument;
const btn = doc.querySelector('[aria-label*="Next" i]');
const btnRect = btn.getBoundingClientRect();
const cx = btnRect.x + btnRect.width/2;
const cy = btnRect.y + btnRect.height/2;
const elAtPoint = doc.elementFromPoint(cx, cy);
const stack = doc.elementsFromPoint(cx, cy).map(el => ({
  tag: el.tagName,
  cls: el.className && el.className.toString().slice(0,60),
  dataSlot: el.getAttribute && el.getAttribute('data-card-slot'),
  ariaLabel: el.getAttribute && el.getAttribute('aria-label'),
  zIndex: getComputedStyle(el).zIndex,
  position: getComputedStyle(el).position,
  pointerEvents: getComputedStyle(el).pointerEvents,
}));
JSON.stringify({
  btnRect: {x: btnRect.x, y: btnRect.y, w: btnRect.width, h: btnRect.height},
  cx, cy,
  elAtPointTag: elAtPoint.tagName,
  elAtPointLabel: elAtPoint.getAttribute('aria-label'),
  stack,
}, null, 1);

const iframe = document.querySelector('#storybook-preview-iframe');
const doc = iframe.contentDocument;
const btn = doc.querySelector('[aria-label*="Next" i]');
const btnRect = btn.getBoundingClientRect();
const cx = btnRect.x + btnRect.width/2;
const cy = btnRect.y + btnRect.height/2;
const topA = doc.elementsFromPoint(cx, cy).find(el => el.tagName === 'A');
const afterStyle = getComputedStyle(topA, '::after');
const beforeStyle = getComputedStyle(topA, '::before');

// Find the carousel data-card-slot wrapper and its computed style
const carouselEl = doc.querySelector('[data-card-slot="carousel"]');
const carouselStyle = carouselEl ? getComputedStyle(carouselEl) : null;

// find ancestor chain of the button up to body, noting position/zIndex/transform/opacity/isolation
let chain = [];
let el = btn;
while (el && el.tagName !== 'HTML') {
  const cs = getComputedStyle(el);
  chain.push({
    tag: el.tagName,
    dataSlot: el.getAttribute && el.getAttribute('data-card-slot'),
    position: cs.position,
    zIndex: cs.zIndex,
    transform: cs.transform,
    opacity: cs.opacity,
    isolation: cs.isolation,
    willChange: cs.willChange,
    mixBlendMode: cs.mixBlendMode,
  });
  el = el.parentElement;
}

// ancestor chain of the <a> up to body
let chainA = [];
let elA = topA;
while (elA && elA.tagName !== 'HTML') {
  const cs = getComputedStyle(elA);
  chainA.push({
    tag: elA.tagName,
    dataSlot: elA.getAttribute && elA.getAttribute('data-card-slot'),
    position: cs.position,
    zIndex: cs.zIndex,
  });
  elA = elA.parentElement;
}

JSON.stringify({
  aHref: topA.getAttribute('href'),
  aClass: topA.className,
  afterContent: afterStyle.content,
  afterPosition: afterStyle.position,
  afterZIndex: afterStyle.zIndex,
  afterInset: afterStyle.inset,
  carouselFound: !!carouselEl,
  carouselPointerEvents: carouselStyle ? carouselStyle.pointerEvents : null,
  carouselPosition: carouselStyle ? carouselStyle.position : null,
  carouselZIndex: carouselStyle ? carouselStyle.zIndex : null,
  buttonAncestorChain: chain,
  aAncestorChain: chainA,
}, null, 1);

