const plpHoverAvail = document.querySelector('[data-cell="plp-hover-avail"]');
const wishlistHoverAvail = document.querySelector('[data-cell="wishlist-hover-avail"]');
const plpHoverUnavail = document.querySelector('[data-cell="plp-hover-unavail"]');
const wishlistHoverUnavail = document.querySelector('[data-cell="wishlist-hover-unavail"]');

function check(cell) {
  if (!cell) return 'CELL NOT FOUND';
  const price = cell.querySelector('[data-card-slot="price"]');
  const sizeChips = cell.querySelector('[data-card-slot="sizeChips"]');
  const notifyMe = cell.querySelector('[data-card-slot="notifyMe"]');
  const attrs = cell.querySelector('[data-testid="card-content-attributes"]');
  return {
    priceDisplay: price ? getComputedStyle(price).display : null,
    sizeChipsDisplay: sizeChips ? getComputedStyle(sizeChips).display : null,
    sizeChipsHTML_hasRadios: sizeChips ? sizeChips.querySelectorAll('[role="radio"]').length : null,
    notifyMeDisplay: notifyMe ? getComputedStyle(notifyMe).display : null,
    attrsExists: !!attrs,
    attrsDisplay: attrs ? getComputedStyle(attrs).display : null,
  };
}

JSON.stringify({
  plpHoverAvail: check(plpHoverAvail),
  wishlistHoverAvail: check(wishlistHoverAvail),
  plpHoverUnavail: check(plpHoverUnavail),
  wishlistHoverUnavail: check(wishlistHoverUnavail),
}, null, 1);

