import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';

const messages = defineMessages({
  positionLabel: {
    id: 'slide_indicator.position.label',
    defaultMessage: 'Image {current} of {total}',
  },
});

const ZIMM_SLIDE_INDICATOR_RECIPE = 'ZimmSlideIndicator';

type ZimmSlideIndicatorProps = {
  /** Total number of images/slides the strip represents. */
  count: number;
  /** Index (0-based) of the currently active/visible slide. Out-of-range values are clamped. */
  activeIndex: number;
};

/**
 * Molecule — read-only image-position indicator for touch devices (tablet + mobile) on the
 * PDP/card image strip. Figma node 40002536:7957 ("Slide indicator"): a segmented 1px hairline
 * strip, one segment per image, the active segment picked out by colour. NOT floating dots.
 *
 * Touch-only per the resolved arrows-vs-indicator split (SFCC-236): hover-capable pointers get
 * prev/next arrow buttons instead (a separate component) and never render this molecule.
 * Because no arrows exist wherever this DOES render, it is the *sole* position signal
 * available there — the root is exposed (`role="group"` + a computed `aria-label`), never
 * `aria-hidden`, while the individual segments are purely decorative (`aria-hidden`) so
 * assistive tech announces the position once via the group label, not once per segment.
 *
 * Renders nothing for `count <= 1` — a single image has no position to indicate among.
 */
export const ZimmSlideIndicator = ({ count, activeIndex }: ZimmSlideIndicatorProps) => {
  const intl = useIntl();

  // Out-of-range clamps rather than throwing: activeIndex < 0 treats as the first slide,
  // activeIndex >= count treats as the last. Written explicitly rather than relying on
  // Array.map/index lookups to silently no-op on an out-of-range value.
  const clampedIndex = Math.min(Math.max(activeIndex, 0), count - 1);

  // Two static resolutions (isActive: false / true), not one per rendered segment — calling
  // useMultiStyleConfig inside the render loop below would be a conditional/looped hook call.
  // Which of the two resolved objects applies to a given segment is picked per-element in the
  // map below instead.
  const styles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: false });
  const activeStyles = useMultiStyleConfig(ZIMM_SLIDE_INDICATOR_RECIPE, { isActive: true });

  // A single image has nothing to indicate a position among.
  if (count <= 1) return null;

  const label = intl.formatMessage(messages.positionLabel, {
    current: clampedIndex + 1,
    total: count,
  });

  return (
    <chakra.div role="group" aria-label={label} __css={styles.root}>
      {Array.from({ length: count }, (_, i) => {
        const isActive = i === clampedIndex;
        return (
          <chakra.div
            key={i}
            aria-hidden
            data-active={isActive ? 'true' : undefined}
            __css={isActive ? activeStyles.dot : styles.dot}
          />
        );
      })}
    </chakra.div>
  );
};

export default ZimmSlideIndicator;

import { createContext, useContext } from 'react';

export type UiCopyContextValue = {
  /**
   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
   * error, or when no `uiCopy` entry with that key exists yet. When `values` is passed,
   * every `{token}` in the resolved string (CMS value or fallback) is replaced from it —
   * mirrors react-intl's `formatMessage(descriptor, values)` shape closely enough that a
   * call site converting away from react-intl only has to change the function, not the
   * string template itself.
   */
  t: (key: string, fallback: string, values?: Record<string, string | number>) => string;
  isLoading: boolean;
};

/**
 * Replaces every `{token}` in `template` with `values[token]`, left untouched if `token`
 * isn't in `values`. Shared by both the real UiCopyProvider and FALLBACK_ONLY below so a
 * key with no matching Contentful entry still interpolates correctly against its fallback.
 */
export const interpolateUiCopy = (template: string, values?: Record<string, string | number>): string => {
  if (!values) return template;
  return template.replace(/\{(\w+)\}/g, (match, token: string) => (token in values ? String(values[token]) : match));
};

/**
 * Populated by UiCopyProvider (overrides/app/components/uiCopyProvider), mounted once in
 * _app-config. Not meant to be consumed directly — call useUiCopy() instead, which supplies
 * the no-Provider fallback.
 */
export const UiCopyContext = createContext<UiCopyContextValue | undefined>(undefined);

const FALLBACK_ONLY: UiCopyContextValue = {
  t: (_key: string, fallback: string, values?: Record<string, string | number>) => interpolateUiCopy(fallback, values),
  isLoading: false,
};

/**
 * App-wide UI-copy lookup, backed by Contentful's uiCopy content type — one entry per string,
 * fetched in a single bulk call by UiCopyProvider and shared via context, the same pattern
 * this app already uses for translations (`useIntl`) rather than the per-page container-fetch
 * pattern commerce-sdk-react hooks use. uiCopy is app-wide static content, not page-specific
 * business data, so it's safe to call from any component — including presentational leaves —
 * without threading it through as a prop.
 *
 * Safe to call with no UiCopyProvider mounted above it (Storybook, an isolated unit test):
 * degrades to fallback-only text instead of throwing, so every call site stays functional and
 * testable with zero setup.
 *
 * @returns `t` lookup function plus `isLoading`
 */
export const useUiCopy = (): UiCopyContextValue => useContext(UiCopyContext) ?? FALLBACK_ONLY;

