import { useState, useEffect } from 'react';
import { getContentfulConfig } from '../config/contentful';
import type { ContentfulAsset } from '../types/contentful';

type ContentfulLink = {
  sys: {
    type: 'Link';
    linkType: 'Asset' | 'Entry';
    id: string;
  };
};

type ContentfulRawEntry = {
  fields: Record<string, ContentfulLink | ContentfulAsset | unknown>;
  [key: string]: unknown;
};

type ContentfulEntriesResponse = {
  items: ContentfulRawEntry[];
  includes?: {
    Asset?: ContentfulAsset[];
  };
};

export const useContentfulEntry = <T>(entryId: string, preview = false) => {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    const fetchEntry = async () => {
      const config = getContentfulConfig();
      if (!config.spaceId || !config.accessToken) {
        setError(new Error('Contentful configuration missing'));
        setIsLoading(false);
        return;
      }

      try {
        const { spaceId, accessToken, previewAccessToken, environment } = config;
        const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
        const token = preview ? previewAccessToken : accessToken;

        // Use the search endpoint with sys.id so include=2 resolves linked assets
        const url = `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?sys.id=${entryId}&access_token=${token}&include=2`;

        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();

        // Resolve linked assets into the entry fields
        const item = result.items[0];
        if (!item) {
          throw new Error(`Entry ${entryId} not found`);
        }
        const resolvedItem = { ...item };
        if (item.fields) {
          Object.keys(item.fields).forEach((fieldKey) => {
            const fieldValue = item.fields[fieldKey] as ContentfulLink;
            if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
              const linked = result.includes?.Asset?.find((asset) => asset.sys.id === fieldValue.sys.id);
              if (linked) resolvedItem.fields[fieldKey] = linked;
            }
          });
        }
        setData(resolvedItem as T);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        setIsLoading(false);
      }
    };

    void fetchEntry();
    return () => controller.abort();
  }, [entryId, preview]);

  return { data, isLoading, error };
};

export const useContentfulEntries = <T>(contentType: string, preview = false) => {
  const [data, setData] = useState<T[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    const fetchEntries = async () => {
      const config = getContentfulConfig();
      if (!config.spaceId || !config.accessToken) {
        setError(new Error('Contentful configuration missing'));
        setIsLoading(false);
        return;
      }

      try {
        const { spaceId, accessToken, previewAccessToken, environment } = config;
        const baseUrl = preview ? 'https://preview.contentful.com' : 'https://cdn.contentful.com';
        const token = preview ? previewAccessToken : accessToken;

        // Include assets in the response
        const url = `${baseUrl}/spaces/${spaceId}/environments/${environment}/entries?content_type=${contentType}&access_token=${token}&include=2`;

        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('Contentful API error response:', errorText);
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();

        // Resolve linked assets
        const resolvedItems = result.items.map((item) => {
          const resolvedItem = { ...item };

          if (item.fields) {
            Object.keys(item.fields).forEach((fieldKey) => {
              const fieldValue = item.fields[fieldKey] as ContentfulLink;
              if (fieldValue?.sys?.type === 'Link' && fieldValue?.sys?.linkType === 'Asset') {
                const assetId = fieldValue.sys.id;
                const linkedAsset = result.includes?.Asset?.find((asset) => asset.sys.id === assetId);
                if (linkedAsset) {
                  resolvedItem.fields[fieldKey] = linkedAsset;
                }
              }
            });
          }

          return resolvedItem;
        });

        setData(resolvedItems as T[]);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
        console.error('Contentful fetch error:', err);
        setError(err instanceof Error ? err : new Error('Unknown error'));
      } finally {
        setIsLoading(false);
      }
    };

    void fetchEntries();
    return () => controller.abort();
  }, [contentType, preview]);

  return { data, isLoading, error };
};

import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the touch-only PDP/card image position indicator — a 1px hairline strip, one
 * segment per image, the current position picked out by colour. Figma node 40002536:7957
 * ("Slide indicator") confirms only the strip's height (1px, flush to the image's bottom edge)
 * and that it is NOT floating dots; per-segment width/gap and the exact colour pairing are not
 * broken out in the export handed to this step, so both are treated as open design decisions
 * (documented below) rather than invented pixel-for-pixel guesses — same precedent as
 * zimmColourSwatchGroup's `pagination` part leaving an unconfirmed inter-button gap at the flex
 * default rather than inventing one.
 *
 * Two parts:
 *   - `root` — the full-width flex strip, exactly `--zimm-scale-025` (1px) tall.
 *   - `dot` — one equal-width segment per image (despite the part name, this renders as a
 *     rectangle in a hairline, not a circular dot — the name matches this component's
 *     already-agreed contract, not a literal shape description).
 */
export const ZimmSlideIndicator = {
  parts: ['root', 'dot'],

  baseStyle: ({ isActive }: { isActive?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      // Fluid, not a fixed Figma px width — matches the product card's own "fluid, not 288px"
      // rule: this strip always spans whatever width its image parent gives it, rather than
      // the specific 159.11px/99.44px bounding boxes the two sampled Figma variants happened
      // to measure at their own artboard widths.
      width: '100%',
      height: 'var(--zimm-scale-025)', // 1px — the one dimension Figma confirms directly.
      // No confirmed inter-segment gap value in the export handed to this step — left at 0
      // (segments flush-adjacent) rather than invented, so the strip reads as one continuous
      // hairline with the active segment picked out by colour alone. Revisit if a designer
      // confirms a real gap value.
      gap: 0,
    },

    dot: {
      // Equal-width segments filling the strip — no confirmed per-segment width ratio exists
      // to justify an unequal split (see root's own comment above).
      flex: '1 0 0',
      height: '100%',
      // Both colours derive from the same grey/900 primitive (see foundation/colour.ts's
      // `opacity` family), so "active" and "inactive" read as solid vs. dimmed versions of one
      // hairline colour rather than two unrelated tones — a reasonable placeholder pairing
      // pending UI-designer confirmation of the exact treatment (only the strip's geometry, not
      // its colour, is confirmed by the Figma export handed to this step).
      background: isActive ? 'var(--zimm-color-bg-05)' : 'var(--zimm-color-opacity-40)',
    },
  }),
};

